#compact-state{display:none}
body[data-player-folded=true]:not([data-art-owner]) .layout{grid-template-columns:minmax(0,1fr);gap:24px}
body[data-player-folded=true]:not([data-art-owner]) .player{position:relative;top:auto;display:grid;grid-template-columns:minmax(0,1fr) 44px 44px;align-items:center;gap:10px;padding:12px 16px;width:100%;min-width:0}
