#player-reveal{width:100%;justify-self:stretch;min-height:58px;padding:6px 12px;gap:12px}#player-reveal strong{font-size:22px}#player-reveal .reveal-copy>span{display:none}
.editor-profile-heading{background:var(--paper);border:1px solid var(--line);border-top:3px solid var(--blue);padding:clamp(18px,3vw,32px)}.editor-profile-heading h1{color:var(--ink)}.producer-note{background:var(--off);border-color:var(--line)}

