#home-install-open,#bookmark-open{font:inherit;font-size:12px;min-height:44px;padding:8px 12px;border:1px solid currentColor;background:transparent;color:inherit;cursor:pointer}
#home-install-dialog,#bookmark-dialog{box-sizing:border-box;width:min(560px,calc(100% - 32px));max-height:calc(100dvh - 32px);overflow:auto;padding:24px;border:1px solid var(--line);background:var(--paper);color:var(--ink)}
#home-install-dialog::backdrop,#bookmark-dialog::backdrop{background:rgba(15,23,42,.58)}
#home-install-dialog h2,#bookmark-dialog h2{font-size:26px;line-height:1.3;margin:0 0 16px}#home-install-dialog h3,#bookmark-dialog h3{font-size:16px}#home-install-dialog p,#bookmark-dialog p,#home-install-dialog li,#bookmark-dialog li{font-size:15px;line-height:1.8}#home-install-dialog ol,#bookmark-dialog ol{padding-left:24px}#home-install-dialog button,#bookmark-dialog button{min-height:44px;min-width:88px;padding:10px 16px;border:1px solid var(--ink);background:var(--ink);color:white;font:inherit;cursor:pointer;margin:8px 8px 0 0}#home-install-dialog :focus-visible,#bookmark-dialog :focus-visible{outline:3px solid var(--blue);outline-offset:3px}
.browser-save-tools[hidden]{display:none}.browser-save-tools{display:flex;flex-wrap:wrap;gap:6px;min-width:0;max-width:100%}.browser-save-tools>button{max-width:100%}@media(max-width:600px){.top nav .browser-save-tools{grid-column:1 / -1;justify-self:start;width:100%}}

/* Supplied finished collages: preserve their full composition and separate existing tag art. */
.feature-card--provided{padding-top:0}
.feature-portrait--provided{height:auto;display:grid;grid-template-rows:auto 64px;gap:8px;background:var(--paper);overflow:hidden}
.feature-portrait--provided .feature-photo{position:static;width:100%;height:auto;aspect-ratio:1456 / 816;object-fit:contain!important;object-position:50% 50%!important;filter:none;mix-blend-mode:normal}
.feature-portrait--provided:after,.feature-portrait--provided .feature-paper-grain,.feature-portrait--provided .feature-tape{display:none}
.feature-portrait--provided .feature-name-tag{position:static;display:block;align-self:center;justify-self:center;width:92%;height:64px;max-height:64px;object-fit:contain;transform:none}
/* The supplied signature is the Editor identity, not a second boxed nameplate. */
.editor-profile-heading{padding:0;border:0;background:transparent;margin:0 0 32px}
.editor-profile-heading h1{margin:0;line-height:1}
.editor-profile-heading .editor-signature{width:min(100%,600px);height:auto;margin:0;object-fit:contain}
.editor-profile-heading .editor-real-name{margin:12px 0 0;font-size:15px;line-height:1.8}
.editor-name-accessible{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

/* Quiet browsing controls: one search rule, spacing for groups, one line per result. */
#view .advanced-filters{border:0;margin:8px 0 20px}
#view .advanced-filters>summary{min-height:44px;padding:10px 0}
#view .crate-sort{border-top:0;padding-top:0;margin-top:12px}
#view .crate-sort select,#view .filter-fields select{min-height:44px}
#view .list-tools{margin:16px 0 24px;gap:16px}
#view #view-toggle{border:0;background:var(--off);color:var(--ink);padding:10px 12px;min-height:44px}
#view .results-pagination{border:0;margin:16px 0;padding:8px 0;gap:8px 16px}
#view .results-pagination button{border:0;background:transparent;padding:8px;min-height:44px}
#view .results-pagination select{border:1px solid var(--line);min-height:44px;background:var(--paper)}
#view .record-row{border-top:0;border-bottom:1px solid var(--line)}
#view .record-row>.record-card{border:0}
#back-to-top.back-to-top-inline{position:static;display:block;width:max-content;max-width:100%;margin:20px 0 20px auto;box-shadow:none;border:0;background:var(--off);min-height:44px}
#back-to-top.back-to-top-inline[hidden],body[data-art-owner] #back-to-top.back-to-top-inline{display:none}
/* Source-led text features remain honest typography, without placeholder portraits. */
.feature-card--text{display:flex;flex-direction:column;justify-content:center;gap:16px;min-height:240px;padding:24px;align-self:start;background:transparent;border:1px solid var(--ink);overflow-wrap:anywhere}
.feature-card--text h3{font-size:clamp(28px,4vw,48px);line-height:1.05}
.feature-card--text p{line-height:1.6}
.feature-card--text:focus-visible{outline:3px solid #4169e1;outline-offset:4px}
.feature-policy{max-width:76ch;line-height:1.8;margin:20px 0 28px}
.feature-archive{margin-top:36px}
.feature-editorial--source-led{max-width:76ch}
.feature-editorial--source-led section{margin-block:32px}
.feature-editorial--source-led .essay-references{font-size:13px;line-height:1.7;overflow-wrap:anywhere}

.feature-portrait--provided .feature-name-typography{display:flex;align-items:center;justify-content:center;font:800 36px/1 var(--display);letter-spacing:.05em;color:var(--ink)}

.editor-photo{margin:24px 0 36px;padding:0;border:0;background:transparent;max-width:100%}.editor-photo img{display:block;width:100%;height:auto;object-fit:contain;border:0;filter:none}.editor-photo figcaption{margin-top:8px;font-size:11px;color:var(--muted)}.editor-photo--event{width:min(100%,720px);margin-top:32px;margin-bottom:40px}

#results.gallery-results.compact-results .record-card .card-main>.catalog-graffiti{display:block!important}.gallery-results .catalog-graffiti{margin:18px 0 0}.static-graffiti-gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:28px}.static-graffiti-gallery>a{display:block;min-width:0}.static-graffiti-gallery .catalog-graffiti{margin-top:12px}.static-graffiti-gallery h2{font-size:24px}

@media(max-width:600px){.top{display:grid;grid-template-columns:minmax(0,1fr);align-items:start}.top nav{width:100%;min-width:0;grid-template-columns:repeat(4,minmax(0,1fr));justify-content:stretch}.top nav>a{min-width:0;font-size:10px;white-space:normal;overflow-wrap:normal;word-break:normal}}

/* Contextual opening is text-only and never replaces the library or transport. */
.opening-selection{padding:0 0 28px;margin:0 0 28px;border-bottom:1px solid var(--line);max-width:760px}.opening-selection h2{font-size:clamp(26px,3vw,38px);line-height:1.2;margin:10px 0 4px}.opening-artist{margin-bottom:14px;font-weight:600}.opening-copy{font-size:18px;line-height:1.7}.opening-reason{font-size:13px;color:var(--muted)}.opening-selection small{display:block;font-size:11px}.opening-selection>a{display:inline-flex;align-items:center;min-height:44px;margin-top:8px;font-size:12px;font-weight:700}

/* Catalog explorer: directly labeled counts, no geographic or popularity inference. */
#catalog-explorer{margin:32px 0 52px;padding-bottom:32px;border-bottom:1px solid #b9bec6}
.ce-heading h2{font-size:clamp(25px,3.4vw,42px);line-height:1.25;margin:12px 0}.ce-heading p{max-width:64ch;line-height:1.8}.ce-heading a{display:inline-flex;align-items:center;min-height:44px}
.ce-scope,.ce-active{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0}.ce-scope button,.ce-active button,.ce-expand,.ce-results>button{min-height:44px;padding:10px 14px;border:1px solid #a8afb9;background:transparent;color:inherit;white-space:normal;max-width:100%;text-align:left}.ce-scope [aria-pressed=true],.ce-chip{background:#183f9f!important;color:white!important;border-color:#183f9f!important}
.ce-current{margin:24px 0}.ce-persistent{font-size:clamp(24px,3vw,38px);font-weight:800;margin:0}.ce-breakdown,.ce-note{font-size:13px;line-height:1.8;color:#4e5664}.ce-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:32px 36px;margin:30px 0}.ce-chart{min-width:0}.ce-chart h3{font-size:20px;margin:0 0 12px}.ce-bars{display:grid;gap:5px}.ce-bar{position:relative;display:flex;align-items:center;justify-content:space-between;gap:16px;width:100%;min-height:44px;padding:10px 12px;border:0;border-bottom:1px solid #d5d9e0;color:#202732;background:linear-gradient(to right,#dce5f7 var(--ce-fill),transparent var(--ce-fill));text-align:left;line-height:1.5}.ce-bar>span{min-width:0;overflow-wrap:anywhere}.ce-bar>b{flex:0 0 auto;font-variant-numeric:tabular-nums}.ce-bar[aria-pressed=true]{outline:2px solid #1743a3;outline-offset:-2px;font-weight:800;background:linear-gradient(to right,#b8ccef var(--ce-fill),transparent var(--ce-fill))}.ce-expand{margin-top:8px}.ce-active p{line-height:1.8;margin:0}.ce-chip{overflow-wrap:anywhere}.ce-results{margin-top:36px}.ce-results h3{font-size:24px}.ce-results h3 span{font-variant-numeric:tabular-nums}.ce-results ol{list-style:none;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 28px}.ce-results li{border-bottom:1px solid #d5d9e0;min-width:0}.ce-results a{display:flex;flex-direction:column;gap:4px;padding:14px 0;min-height:44px;overflow-wrap:anywhere}.ce-results a span{color:#4e5664;font-size:13px}.ce-static .ce-bar{cursor:default}.ce-static .ce-bar span{min-width:0}.ce-static details>summary{min-height:44px;padding:12px 0;cursor:pointer}
#catalog-explorer button:focus-visible,#catalog-explorer a:focus-visible{outline:3px solid #1743a3;outline-offset:3px}#timeline-reading{scroll-margin-top:24px}
@media(max-width:600px){.ce-grid,.ce-results ol{grid-template-columns:1fr}.ce-grid{gap:28px}.ce-bar{font-size:14px}.ce-heading h2{font-size:27px}.ce-note{font-size:12px}.ce-scope button{flex:0 1 auto}.ce-current{margin:20px 0}}

#catalog-explorer .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
